-- =========================================================================
-- DADOS DA TABELA: gihs_core.knowledge_articles (15 registros sincronizados)
-- =========================================================================
INSERT INTO gihs_core."knowledge_articles" ("id", "code", "title", "sector", "category", "service_type", "summary_solution", "detailed_procedure", "estimated_resolution_minutes", "tags", "useful_count", "author", "last_updated", "created_at")
VALUES
  ('KB-ADM-001', 'ADM-PAT-01', 'Substituição Emergencial de Equipamento e Emissão de Termo de Cautela', 'Administrativo', 'Hardware & Periféricos', 'Substituição de Hardware & Termo de Cautela', 'Separação de notebook reserva homologado do estoque central, clonagem da imagem padrão da empresa e coleta de assinatura no termo patrimonial.', '["Conferir disponibilidade de equipamento sobressalente no inventário patrimonial TI.","Transferir termo de cautela no sistema para o novo número de patrimônio (PAT).","Restaurar backup de arquivos e perfil de usuário a partir do storage corporativo.","Entregar o equipamento ao colaborador com conferência física de carregador e periféricos.","Encaminhar máquina defeituosa para reparo autorizado e atualizar status no inventário."]', 60, '["patrimonio","notebook","estoque","termo de cautela","administrativo"]', 31, 'Helena Santos', '2026-09-27T15:13:03.152Z', '2026-09-27T15:13:03.152Z'),
  ('KB-BE-001', 'BE-API-01', 'Depuração de Erro 502 Bad Gateway no Endpoint de Checkout e Pix', 'Back-End', 'Aplicações & APIs', 'Depuração de API & Microsserviços', 'Reinicio dos pods do microsserviço de pagamento, revalidação do pool de conexões HTTP keep-alive e reprocessamento de mensagens na fila dead-letter.', '["Analisar logs centralizados no Elasticsearch / CloudWatch filtrando por status 502.","Verificar se o gateway intermediário (ex: Banco Central / PSP) está com instabilidade.","Reiniciar instâncias do container com tráfego travado.","Validar fila de dead-letter no RabbitMQ e acionar worker de reprocessamento seguro.","Efetuar transação simulada em sandbox e checar retorno 200 OK com webhook confirmado."]', 40, '["api","502","pix","gateway","backend","microsservicos","rabbitmq"]', 51, 'Rodrigo Fontes', '2026-09-27T15:13:02.902Z', '2026-09-27T15:13:02.902Z'),
  ('KB-DBA-001', 'DBA-PERF-01', 'Otimização de Query com Sequential Scan e Criação de Índices B-Tree', 'DBA', 'Bancos de Dados', 'Otimização de Query & Banco de Dados', 'Execução de EXPLAIN ANALYZE no schema de produção, constatação de full-scan em tabela de faturamento/rastreamento e criação de índice composto parcial.', '["Coletar a query em lentidão no log de slow queries (pg_stat_statements).","Rodar \"EXPLAIN (ANALYZE, BUFFERS) [QUERY]\" para mapear o custo de execução.","Identificar filtros que não utilizam índices (ex: campos de data ou status).","Criar índice com comando CONCURRENTLY para não travar gravações em produção.","Executar \"ANALYZE [TABELA]\" para recalcular as estatísticas do planejador PostgreSQL.","Verificar redução do tempo de resposta de segundos para milissegundos."]', 50, '["dba","postgres","query","indice","performance","slow query","sql"]', 63, 'Camila Rocha', '2026-09-27T15:13:02.402Z', '2026-09-27T15:13:02.402Z'),
  ('KB-DBA-002', 'DBA-LOCK-02', 'Destravamento de Conexões Travadas em "idle in transaction" e Deadlocks', 'DBA', 'Bancos de Dados', 'Destravamento de Locks & Conexões DBA', 'Identificação de PIDs em espera na view pg_stat_activity, análise do grafo de lock e cancelamento da consulta bloqueadora com pg_cancel_backend.', '["Executar consulta para listar queries com espera superior a 30 segundos.","Mapear qual transação está mantendo o RowExclusiveLock ou AccessExclusiveLock.","Tentar cancelamento suave com \"SELECT pg_cancel_backend(pid)\".","Se não responder em 10 segundos, finalizar a conexão com \"SELECT pg_terminate_backend(pid)\".","Notificar os desenvolvedores para revisão de transações sem COMMIT/ROLLBACK no código."]', 30, '["deadlock","lock","postgres","transacao","pool","dba"]', 35, 'Lucas Almeida', '2026-09-27T15:13:02.527Z', '2026-09-27T15:13:02.527Z'),
  ('KB-FE-001', 'FE-UI-01', 'Correção de Desalinhamento e Quebra de Layout em Dispositivos Móveis', 'Front-End', 'Aplicações & APIs', 'Correção de Layout & Interface Web', 'Ajuste de classes utilitárias de overflow e viewport em tabelas responsivas, testes de viewport em resoluções 360px a 768px e deploy de hotfix.', '["Reproduzir o problema no emulador DevTools simulando iPhone e Android.","Inspecionar containers com largura fixa ou ausência de min-w-0 / overflow-x-auto.","Ajustar quebras de linha com white-space: nowrap nos crachás e botões operacionais.","Validar acessibilidade de toque (área mínima 44px) e contraste de cores WCAG AA.","Realizar commit no repositório e executar pipeline de CI/CD para release da interface."]', 30, '["frontend","layout","responsivo","css","mobile","interface"]', 26, 'Beatriz Lima', '2026-09-27T15:13:03.027Z', '2026-09-27T15:13:03.027Z'),
  ('KB-N1-001', 'N1-AUTH-01', 'Reset de Credenciais de Rede & Ativação de MFA / 2FA', 'N1', 'Acessos & Identidade', 'Reset de Credenciais & 2FA', 'Validação de identidade via gestor, reset de senha temporária no Active Directory e pareamento de autenticador TOTP com código de backup.', '["Confirmar identidade do solicitante por canal oficial com validação da chefia imediata.","Acessar o console do Active Directory / Identity Provider.","Definir senha provisória de alta entropia com flag \"Exigir troca no próximo logon\".","Revogar sessões ativas e registrar novo código de emparelhamento MFA no Authenticator.","Testar login em ambiente de homologação e notificar o usuário com instruções seguras."]', 15, '["senha","mfa","totp","active directory","login","acesso"]', 48, 'Mariana Castro', '2026-09-27T15:13:01.385Z', '2026-09-27T15:13:01.385Z'),
  ('KB-N1-002', 'N1-HW-02', 'Falha de Spooler e Impressora Fiscal PDV sem Comunicação', 'N1', 'Hardware & Periféricos', 'Configuração de Periféricos & PDV', 'Parada do serviço Spooler, expurgo da fila em disco C:\Windows\System32\spool\PRINTERS, reinício do serviço e teste de impressão de cupom fiscal.', '["Executar prompt de comando como Administrador: \"net stop spooler\".","Navegar até a pasta \"C:\\Windows\\System32\\spool\\PRINTERS\" e deletar arquivos .shd e .spl retidos.","Reiniciar o serviço com \"net start spooler\".","Desconectar e reconectar o cabo USB/Serial da impressora térmica.","Imprimir página de teste pelo driver do fabricante e validar no software do PDV."]', 20, '["impressora","pdv","spooler","fiscal","varejo","hardware"]', 32, 'Gabriel Ribeiro', '2026-09-27T15:13:01.527Z', '2026-09-27T15:13:01.527Z'),
  ('KB-N1-003', 'N1-MAIL-03', 'Criação e Provisionamento de Contas Corporativas de E-mail', 'N1', 'Acessos & Identidade', 'Provisionamento de Contas & E-mail', 'Criação da caixa postal com domínio corporativo, atribuição de licença, inclusão nos grupos de distribuição do setor e envio de guia de boas-vindas.', '["Consultar ticket de solicitação aprovado pelo RH/Gestão com nome completo e cargo.","Acessar painel corporativo do Workspace / Exchange Admin Center.","Criar usuário no formato \"nome.sobrenome@empresa.com.br\".","Atribuir licença padrão do colaborador e vincular aos grupos do setor correspondente.","Configurar encaminhamentos e políticas de retenção padrão LGPD.","Enviar credenciais e guia de primeiro acesso via canal criptografado."]', 25, '["email","workspace","exchange","onboarding","novo colaborador"]', 29, 'Larissa Lima', '2026-09-27T15:13:01.652Z', '2026-09-27T15:13:01.652Z'),
  ('KB-N2-001', 'N2-NET-01', 'Falha de Rota no Gateway e Desconexão de Túnel VPN IPsec', 'N2', 'Redes & Conectividade', 'Diagnóstico de Rota & Conectividade VPN', 'Reinicialização do túnel IPsec Fase 1 e 2 no concentrador de borda, verificação de rotas estáticas na tabela do roteador filial e teste de MTU.', '["Efetuar teste de ping e traceroute até o gateway da filial afetada.","Acessar a interface de gerência do firewall corporativo (Fortinet / pfSense).","Verificar o status dos túneis IPsec: logs de renegotiation e correspondência de Phase 1/2.","Executar comando de reset do túnel: \"vpn ipsec tunnel reset [nome-do-tunel]\".","Conferir MTU para evitar fragmentação de pacotes (ajustar MSS clamping se necessário).","Confirmar tráfego bidirecional através de captura de pacotes tcpdump."]', 40, '["vpn","ipsec","rota","gateway","rede","filial","firewall"]', 54, 'Victor Estevão', '2026-09-27T15:13:01.778Z', '2026-09-27T15:13:01.778Z'),
  ('KB-N2-002', 'N2-SYS-02', 'Latência Crítica e Esgotamento de Recursos em Estações Locais', 'N2', 'Sistemas & ERP', 'Otimização de Sistema & Performance', 'Análise de processos zumbis, limpeza de cache DNS/WINS, liberação de espaço em disco e ajuste no arquivo hosts/serviços de rede.', '["Acessar a máquina remotamente via AnyDesk ou SSH corporativo.","Identificar processos consumindo 100% de CPU ou IO de disco com Resource Monitor / top.","Executar limpeza de DNS: \"ipconfig /flushdns\" e renovação DHCP.","Expurgar caches temporários em %temp% e logs acumulados.","Verificar se o software antivírus corporativo travou em scanning recursivo e reiniciar agente."]', 35, '["latencia","desempenho","lentidao","windows","memoria","disco"]', 22, 'Juliana Pires', '2026-09-27T15:13:01.902Z', '2026-09-27T15:13:01.902Z'),
  ('KB-N2-003', 'N2-SEC-03', 'Desbloqueio de IP Bloqueado por Tentativas Consecutivas de Acesso', 'N2', 'Segurança & LGPD', 'Desbloqueio de IP & Políticas de Segurança', 'Verificação da lista de Fail2Ban e tabelas de drop do firewall, validação com o usuário para evitar ataque de dicionário e liberação da regra.', '["Consultar log de auditoria do firewall buscando o IP público do cliente/filial.","Identificar motivo do bloqueio (ex: 5 falhas no serviço RDP ou SMTP em 2 minutos).","Confirmar que a máquina que gerou as requisições é legítima e passou por checagem antivírus.","Remover IP da tabela de ban temporário com \"pfctl -t abusive_hosts -T delete [IP]\".","Reorientar o usuário sobre o número máximo de tentativas de senha."]', 20, '["bloqueio","firewall","fail2ban","ip","segurança","acesso"]', 38, 'Victor Estevão', '2026-09-27T15:13:02.027Z', '2026-09-27T15:13:02.027Z'),
  ('KB-N3-001', 'N3-BGP-01', 'Comutação Emergencial de Link Dedicado e Failover BGP', 'N3', 'Redes & Conectividade', 'Comutação de Link & Roteamento BGP', 'Abertura de ticket emergencial na operadora de telecom, ajuste de AS-Path prepending e comutação forçada para a rota de backup sem perda de pacotes.', '["Monitorar status das sessões BGP no roteador de borda (show ip bgp summary).","Constatar perda de pacotes ou instabilidade no ASN do provedor primário.","Elevar a Local Preference da rota alternativa ou aplicar prepend na rota primária degradada.","Validar propagação do tráfego nos concentradores de borda externos.","Registrar chamado com o NOC da operadora e acompanhar SLA de restauração."]', 60, '["bgp","datacenter","link dedicado","operadora","failover","infraestrutura"]', 41, 'Carlos Eduardo', '2026-09-27T15:13:02.152Z', '2026-09-27T15:13:02.152Z'),
  ('KB-N3-002', 'N3-VIRT-02', 'Esgotamento de Memória / CPU em Host de Virtualização Proxmox/VMware', 'N3', 'Infraestrutura & Nuvem', 'Balanceamento de Recursos de Virtualização', 'Execução de Live Migration de instâncias não críticas para nó secundário do cluster, compactação de volumes e redimensionamento de pools de RAM.', '["Identificar nós do cluster com utilização acima de 85% de CPU/RAM.","Acionar live migration (vMotion) das VMs de baixa prioridade para hosts ociosos.","Verificar integridade do armazenamento SAN/NFS compartilhado.","Ajustar reserva dinâmica de memória (memory ballooning).","Confirmar estabilização dos alarmes no dashboard Zabbix / Grafana."]', 45, '["virtualizacao","vmware","proxmox","cluster","servidor","datacenter"]', 19, 'Carlos Eduardo', '2026-09-27T15:13:02.277Z', '2026-09-27T15:13:02.277Z'),
  ('KB-SEC-001', 'SEC-AUD-01', 'Auditoria de Chaves SSH e Rotação de Certificados TLS/SSL', 'Cyber Security', 'Segurança & LGPD', 'Auditoria de Segurança & Certificados', 'Auditoria automatizada nos arquivos authorized_keys do cluster, revogação de acessos desligados e emissão de novo certificado wildcard com Let''s Encrypt.', '["Executar script de auditoria de conformidade em todos os servidores produtivos.","Cruzar a lista de chaves públicas autorizadas com o organograma de colaboradores ativos.","Remover credenciais de ex-colaboradores e chaves fracas (RSA < 3072 ou ECDSA legado).","Verificar expiração de certificados de borda no Traefik/Nginx e renovar via Certbot.","Gerar relatório de conformidade criptografado e anexar à auditoria do sistema."]', 55, '["seguranca","ssh","ssl","tls","certificado","lgpd","criptografia"]', 44, 'Lucas Martins', '2026-09-27T15:13:02.653Z', '2026-09-27T15:13:02.653Z'),
  ('KB-SEC-002', 'SEC-MAL-02', 'Resposta a Incidente de Tentativa de Phishing e Engenharia Social', 'Cyber Security', 'Segurança & LGPD', 'Resposta a Incidentes & Phishing', 'Análise de cabeçalhos de e-mail (SPF/DKIM/DMARC), bloqueio de domínios maliciosos nas regras de transporte e expurgo de caixas postais corporativas.', '["Coletar arquivo .eml do e-mail suspeito enviado por usuário.","Analisar IPs de origem e autenticação SPF/DKIM/DMARC.","Extrair URLs e hashes de anexos para consulta em sandbox (VirusTotal).","Bloquear remetente e domínio nas políticas de segurança do mail gateway.","Executar busca e expurgo em lote no servidor de e-mail para remover mensagens idênticas.","Publicar comunicado preventivo no canal corporativo de segurança."]', 45, '["phishing","segurança","email","dmarc","incidente","soc"]', 37, 'Fernanda Costa', '2026-09-27T15:13:02.778Z', '2026-09-27T15:13:02.778Z')
ON CONFLICT DO NOTHING;

